begin DagothUrCreature2

short state
float timer
short teleportDisabled

if ( teleportDisabled == 0 )
	DisableTeleporting
	Set teleportDisabled to 1
endif

if ( Menumode == 1 )
	return
endif

;return if heart is destroyed, so he can be killed
if ( HeartDestroyed == 1 )
	if ( GetHealth > 200 )
		SetHealth 200
	endif
	if ( GetMagicka > 0 )
		SetMagicka 0
	endif
	return
endif

;keep alive
if ( GetHealth < 1000 )
	SetHealth 1000		
endif

;infinite spells
if ( GetMagicka < 100 )
	SetMagicka 1000
endif

if  ( state == 0 )

	if ( timer < 1 )
		Set timer to ( timer + GetSecondsPassed )
		return
	endif

	Set timer to 0

	;play initial greeting, once
	Player->Say, "Vo\Misc\Dagoth Ur Welcome C.wav", "Que tolo você é. Eu sou um deus. Como se pode matar um deus? Que inocência grandiosa e embriagante. Como pôde ser tão ingênuo? Não há escapatória. Nem Retorno nem Intervenção podem funcionar neste lugar. Venha. Deponha suas armas. Ainda não é tarde demais para a minha misericórdia."
	set state to 10
endif

if ( "heart_akulakhan".countHits == 0 )

	;if Dagoth has not been hit or it is reset, reset dagoth's shields

	if ( GetSpell "dagoth_ur_shield_01" == 0 )
		AddSpell "dagoth_ur_shield_01"
	endif

	if ( GetSpell "dagoth_ur_shield_02" == 1 )
		RemoveSpell "dagoth_ur_shield_02"
	endif

	if ( GetSpell "dagoth_ur_shield_03" == 1 )
		RemoveSpell "dagoth_ur_shield_03"
	endif

	if ( GetSpell "dagoth_ur_shield_04" == 1 )
		RemoveSpell "dagoth_ur_shield_04"
	endif

endif

if ( "heart_akulakhan".countHits == 1 )

	if ( GetSpell "dagoth_ur_shield_01" == 1 )
		RemoveSpell "dagoth_ur_shield_01"
	endif

	if ( GetSpell "dagoth_ur_shield_02" == 0 )
		AddSpell "dagoth_ur_shield_02"
	endif

endif

if ( "heart_akulakhan".countHits == 2 )

	if ( GetSpell "dagoth_ur_shield_02" == 1 )
		RemoveSpell "dagoth_ur_shield_02"
	endif

	if ( GetSpell "dagoth_ur_shield_03" == 0 )
		AddSpell "dagoth_ur_shield_03"
	endif

endif

if ( "heart_akulakhan".countHits == 3 )

	if ( GetSpell "dagoth_ur_shield_03" == 1 )
		RemoveSpell "dagoth_ur_shield_01"
	endif

	if ( GetSpell "dagoth_ur_shield_04" == 0 )
		AddSpell "dagoth_ur_shield_04"
	endif

endif

if ( "heart_akulakhan".countHits == 4 )

	if ( GetSpell "dagoth_ur_shield_01" == 1 )
		RemoveSpell "dagoth_ur_shield_01"
	endif

	if ( GetSpell "dagoth_ur_shield_02" == 1 )
		RemoveSpell "dagoth_ur_shield_02"
	endif

	if ( GetSpell "dagoth_ur_shield_03" == 1 )
		RemoveSpell "dagoth_ur_shield_03"
	endif

	if ( GetSpell "dagoth_ur_shield_04" == 1 )
		RemoveSpell "dagoth_ur_shield_04"
	endif

endif		

End

Begin pillowScript

short comfy

if ( PCVampire == 1 )
	return
endif

if ( comfy == -1 )
	if ( player->GetItemCount "misc_uni_pillow_unique" > 0 )
		if ( GetPCSleep == 0 )
			set comfy to 0
			return
		endif
	endif
endif


if ( comfy == 0 )
	if ( player->GetItemCount "misc_uni_pillow_unique" > 0 )
		if ( GetPCSleep == 1 )
			MessageBox "Seu sono é muito repousante em seu Travesseiro Ultraconfortável"
			set comfy to -1
			return
		endif
	endif
endif


End pillowScript
